pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        uint256 initialBalance = address(c).balance;
        vm.deal(address(c), 100);

        bool claimed;
        try c.getFirstWithdrawalBonus(recipient) {
            claimed = true;
        } catch {
            claimed = false;
        }

        uint256 finalBalance = address(c).balance;
        assertTrue(!claimed || finalBalance == 0);
    }
}
